// Integrated practice, spaced review and learning rewards.
const DAY=86400000;
const cleanInt=n=>Number.isFinite(Number(n))?Math.max(0,Math.floor(Number(n))):0;
let game={xp:cleanInt(saved.game?.xp),missions:cleanInt(saved.game?.missions),correct:cleanInt(saved.game?.correct),days:Array.isArray(saved.game?.days)?saved.game.days.filter(d=>typeof d==='string').slice(-365):[],awards:Array.isArray(saved.game?.awards)?saved.game.awards.filter(a=>typeof a==='string'):[]};
