const baseSummary=summary;
summary=function(){baseSummary();if(!$('gamePanel'))return;const level=1+Math.floor(game.xp/100);$('gamePanel').innerHTML=`<div class="game-stats"><span><b>${game.xp}</b> נקודות</span><span><b>${level}</b> רמה</span><span><b>${game.missions}</b> משימות</span></div><label for="levelProgress">עוד ${100-game.xp%100} נקודות לרמה הבאה</label><progress id="levelProgress" max="100" value="${game.xp%100}"></progress><div class="badges">${achievements.map(([id,label])=>`<span class="badge ${game.awards.includes(id)?'earned':''}">${game.awards.includes(id)?'★':'☆'} ${label}</span>`).join('')}</div>`;};
const baseMark=mark;
mark=function(ok){const w=deck[index];baseMark(ok);const s=stats[w.en];const now=Date.now();s.streak=ok?cleanInt(s.streak)+1:0;s.due=now+(ok?[1,3,7,14,30][Math.min(s.streak-1,4)]*DAY:5*60000);s.lastReviewed=now;
if(ok&&s.rewardDay!==dayKey()){game.xp+=10;game.correct++;s.rewardDay=dayKey();if(!game.days.includes(dayKey()))game.days.push(dayKey());}
for(const [id,,test]of achievements)if(test()&&!game.awards.includes(id))game.awards.push(id);persist();summary();};
const baseBuild=buildDeck;
buildDeck=function(){if(mode===4){startMission();return;}baseBuild();};
function eligible(){const f=$('filter').value;return words.filter(w=>f==='all'||f==='core'&&!w.extra||f==='extra'&&w.extra||f==='focus'&&stats[w.en]?.focus);}
let stopPenalty=null,penaltySelection={club:0,player:0};
