const chosen=candidates.slice(0,5),count=Math.min(chosen.filter(w=>w.cloze?.includes('___')).length,game.missions%2===0?2:1),clozeWords=new Set(chosen.filter(w=>w.cloze?.includes('___')).slice(-count||chosen.length).map(w=>w.en));
