onAttempt:(i,ok,attempt)=>{deck=mission.map(q=>q.w);index=i;step=i;if(!ok&&attempt===1)mark(false);if(ok&&attempt===1){mark(true);missionCorrect++;}if(ok||attempt===2){answered.add(i);$('position').textContent=(i+1)+' מתוך '+mission.length;$('bar').style.width=(100*(i+1)/mission.length)+'%';}},
