const cta=document.createElement('button');cta.className='primary mission-cta';cta.dataset.mode='4';cta.setAttribute('aria-pressed','false');cta.textContent='עולים למגרש · 5 בעיטות ⚽';cta.onclick=()=>{mode=4;startMission();document.querySelector('.workspace').scrollIntoView({behavior:'smooth',block:'start'});};document.querySelector('.hero').append(cta);
// The learning cards are the word feed. Swipe vertically; controls remain available.
