$('stage').tabIndex=0;$('stage').setAttribute('aria-label','כרטיס לימוד או שאלת תרגול');$('stage').addEventListener('keydown',e=>{if(mode===0&&e.target===$('stage')&&deck.length&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();index=e.key==='ArrowDown'?(index+1)%deck.length:Math.max(0,index-1);render();}});
for(const id of ['reset','restore','import']){const original=$(id).onclick;$(id).onclick=()=>{const before=words;const beforeStats=stats;original();if(stats!==beforeStats||words!==before){game={xp:0,missions:0,correct:0,days:[],awards:[]};persist();summary();if(mode===4)startMission();}};}
